const sky = nightSky(scene); sky.sky.material.depthWrite = true; sky.clouds.forEach((c, i) => c.position.set(-800 + i * 170, 360 + (i % 3) * 70, -1400)); { const u = sky.sky.material.uniforms; u.top.value.setRGB(.26, .6, .98); u.mid.value.setRGB(.5, .78, 1); u.hor.value.setRGB(.78, .9, 1); sky.moon.visible = false; }
const hemi = new THREE.HemisphereLight(0xdcebff, 0x9a8a78, 1.8); scene.add(hemi);
