// ---------- escenarios ----------
const NX = 1000, CX = 1200, HX = 1400, GX = 1600, FX = 1800, TX = 2000, OX = 2200, PX = 2400, RX = 2600;
const OUT = outdoor(scene), NUR = nursery(scene, NX), CLS = classroom(scene, CX), HAL = hallway(scene, HX), GYM = gym(scene, GX), CAF = cafeteria(scene, FX), STR = stairs(scene, TX), OFF = office(scene, OX), HH = hospHall(scene, PX), HR = hospRoom(scene, RX);
