const lukas = makeLukas(scene), jonas = makeJonas(scene), sis = makeSister(scene), mom = makeMom(scene), doc = makeDoctor(scene), coach = makeCoach(scene), prin = makePrincipal(scene), medics = [0, 1].map(i => makeMedic(scene, i));
